// The curated exercise library. Source of truth for the seed migration
// (generated by `pnpm db:gen-library`) and for tests / the template plan.
// Runtime code reads exercises from the database.

import type { BodyPart, Equipment, ExerciseCategory, Metric } from "@/lib/constants";

export type Exercise = {
  id: string;
  name: string;
  category: ExerciseCategory;
  chain: string;
  chain_order: number;
  level: number;
  equipment: Equipment[];
  metric: Metric;
  unilateral: boolean;
  cues: string[];
  contraindications: BodyPart[];
  media_url: string | null;
};

type Def = [
  id: string,
  name: string,
  level: number,
  metric: Metric,
  equipment: Equipment[],
  contraindications: BodyPart[],
  cues: string[],
  unilateral?: boolean,
];

function chain(category: ExerciseCategory, chainName: string, defs: Def[]): Exercise[] {
  return defs.map(([id, name, level, metric, equipment, contraindications, cues, unilateral], i) => ({
    id,
    name,
    category,
    chain: chainName,
    chain_order: i + 1,
    level,
    equipment,
    metric,
    unilateral: unilateral ?? false,
    cues,
    contraindications,
    media_url: null,
  }));
}

